import Foundation

extension SocialSupportGuides {
    static let familyBenefits = DirectoryGuide(
        cardSummary: .init(ukrainian: "Familienbeihilfe, Kinderbetreuungsgeld і зміни для переміщених", german: "Familienbeihilfe, Kinderbetreuungsgeld und Regeln für Vertriebene"),
        introduction: .init(ukrainian: "Це різні виплати з різними заявами. Для переміщених з України парламент ухвалив зміни, але їх чинність потрібно перевіряти за публікацією закону та періодом виплати.", german: "Das sind getrennte Leistungen mit getrennten Anträgen. Für Ukraine-Vertriebene wurden Änderungen beschlossen; Geltung nach Kundmachung und Bezugszeitraum prüfen."),
        sections: [
            .init("family-eligibility", "figure.child", "Перевірте право на Familienbeihilfe", "Anspruch auf Familienbeihilfe prüfen", "Звірте статус дитини й заявника, центр життєвих інтересів в Австрії та період, за який потрібна виплата. Для повнолітніх дітей діють додаткові правила щодо навчання й власного доходу. Для переміщених осіб з України окремо перевірте правила 2026 року про Grundversorgung; не припускайте, що статус автоматично дає виплату.", "Status von Kind und antragstellender Person, Lebensmittelpunkt in Österreich und gewünschten Bezugszeitraum prüfen. Für volljährige Kinder gelten zusätzliche Ausbildungs- und Einkommensregeln. Für Ukraine-Vertriebene die 2026er Grundversorgungsregeln gesondert prüfen; der Status allein begründet keine automatische Zahlung.", source: familyPayment),
            .init("family-apply", "doc.text", "Подайте заяву до Finanzamt", "Antrag beim Finanzamt stellen", "Заяву на Familienbeihilfe подавайте до Finanzamt Österreich, зокрема через FinanzOnline. Підготуйте дані дитини, родинний зв’язок, проживання, статус і запитані докази. За загальним правилом виплату можна призначити заднім числом не більш ніж за п’ять років від місяця подання; це не скасовує спеціальні умови для кожного періоду. Збережіть підтвердження заяви й рішення.", "Familienbeihilfe beim Finanzamt Österreich beantragen, auch über FinanzOnline. Angaben zu Kind, Verwandtschaft, Wohnsitz, Status und angeforderte Belege vorbereiten. Allgemein ist eine rückwirkende Gewährung höchstens fünf Jahre ab Antragsmonat möglich; besondere Voraussetzungen je Zeitraum bleiben maßgeblich. Antragseingang und Entscheidung aufbewahren.", source: familyPayment),
            .init("new-law", "calendar.badge.clock", "Зміни для переміщених у 2026 році", "Änderung für Vertriebene 2026", "На 11.10.2026 парламент ухвалив зміни до Familienbeihilfe та Kinderbetreuungsgeld, але офіційний портал називає днем набуття чинності день після оприлюднення в Bundesgesetzblatt. Законопроєкт передбачає правила з 01.07.2026 без вимоги праці або реєстрації в AMS, а також обмеження одночасного отримання Familienbeihilfe та Grundversorgung з винятком для дітей зі значною інвалідністю. Перед рішенням про відмову від допомоги перевірте оприлюднення і письмово з’ясуйте наслідки у Finanzamt та земельній службі.", "Stand 11.10.2026 sind Änderungen zu Familienbeihilfe und Kinderbetreuungsgeld parlamentarisch beschlossen; laut amtlichem Portal treten sie erst am Tag nach Kundmachung im Bundesgesetzblatt in Kraft. Der Beschluss sieht Regeln ab 01.07.2026 ohne Erwerbs- oder AMS-Erfordernis sowie eine Einschränkung des gleichzeitigen Bezugs von Familienbeihilfe und Grundversorgung vor, mit Ausnahme bei erheblich behinderten Kindern. Vor Verzicht auf Unterstützung Kundmachung und Folgen schriftlich bei Finanzamt und Landesstelle klären.", source: familyStatus),
            .init("kbg-model", "heart", "Оберіть модель Kinderbetreuungsgeld", "Kinderbetreuungsgeld-Modell wählen", "Після народження дитини порівняйте паушальну й залежну від доходу моделі, тривалість, поділ між батьками та граничний додатковий заробіток. Перевірте право на Familienbeihilfe і необхідні огляди Eltern-Kind-Pass: відсутні підтвердження можуть зменшити виплату. Після першої заяви змінити систему можна лише протягом 14 днів; визначте вибір до подання.", "Nach der Geburt pauschales und einkommensabhängiges Modell, Bezugsdauer, Aufteilung zwischen Eltern und Zuverdienstgrenze vergleichen. Anspruch auf Familienbeihilfe und nötige Eltern-Kind-Pass-Untersuchungen prüfen: fehlende Nachweise können die Leistung mindern. Ein Systemwechsel ist nur binnen 14 Tagen ab dem ersten Antrag möglich; daher vorher entscheiden.", source: kbgSystems),
            .init("kbg-apply", "checklist", "Kinderbetreuungsgeld: не пропустіть строк", "Kinderbetreuungsgeld rechtzeitig beantragen", "Заяву подавайте до відповідальної медичної страхової установи, за потреби через її цифровий сервіс. Паушальне Kinderbetreuungsgeld можна заявити заднім числом максимум за 182 дні, тому звертайтеся невдовзі після народження. Підготуйте дані батьків і дитини, статус, страхування та підтвердження оглядів; попросіть перелік для вашої моделі.", "Antrag beim zuständigen Krankenversicherungsträger stellen, gegebenenfalls digital. Pauschales Kinderbetreuungsgeld kann höchstens 182 Tage rückwirkend beansprucht werden; daher bald nach Geburt beantragen. Angaben zu Eltern und Kind, Status, Versicherung und Untersuchungsnachweise bereithalten; Unterlagenliste für das gewählte Modell erfragen.", source: kbgApplication),
            .init("coordination", "arrow.triangle.2.circlepath", "Узгодьте виплати з Grundversorgung", "Leistungen mit Grundversorgung abstimmen", "Kinderbetreuungsgeld може враховуватися як дохід при розрахунку Grundversorgung. Перед подачею або після нового рішення повідомте земельну службу та попросіть письмово перерахувати підтримку й медичне покриття. Familienbeihilfe має окремі правила: через зміну закону 2026 року не робіть самостійних висновків про сумісність чи повернення грошей.", "Kinderbetreuungsgeld kann bei der Grundversorgung als Einkommen berücksichtigt werden. Vor Antrag oder nach neuem Bescheid die Landesstelle informieren und Unterstützung sowie Krankenversorgung schriftlich neu berechnen lassen. Für Familienbeihilfe gelten eigene Regeln: wegen der Gesetzesänderung 2026 keine eigenständigen Annahmen zu Parallelbezug oder Rückforderung treffen.", source: ukraine)
        ], sources: [familyPayment, childPayment, kbgSystems, kbgApplication, familyStatus, familyLaw, ukraine]
    )
}
